=\\\"text\\\" /></td></tr><tr><td colspan=\\\"2\\\">8/91</td></tr></table></td><td><table><tr><td colspan=\\\"2\\\">Please Choose Method of Payment:</td></tr><tr><td><input type=\\\"checkbox\\\" /> Check payable to the Superintendent of Documents</td><td></td></tr><tr><td><input type=\\\"checkbox\\\" /> GPO Deposit Account <input type=\\\"text\\\" /></td><td></td></tr><tr><td><input type=\\\"checkbox\\\" /> VISA or MasterCard Account <input type=\\\"text\\\" /></td><td></td></tr></table></td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [23, 1227, 1156, 1273], \"page_id\": 144}], \"content\": \"Mail To: Superintendent of Documents, Government Printing Office, Washington, DC 20402-9325\", \"description\": null, \"id\": 10, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [18, 1364, 466, 1422], \"page_id\": 144}], \"content\": \"Form can be photocopied.\", \"description\": null, \"id\": 11, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [207, 38, 1232, 75], \"page_id\": 147}], \"content\": \"Information about the Superintendent of Documents Subscription Service\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [38, 108, 274, 141], \"page_id\": 147}], \"content\": \"Current Subscribers\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [38, 139, 1396, 243], \"page_id\": 147}], \"content\": \"To know when to expect your renewal notice and keep a good thing coming... to keep subscription prices down, the Government Printing Office mails each subscriber only one renewal notice. You can learn when you will get your renewal notice by checking the number that follows ISSDUE on the top line of your label as shown in this example:\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [43, 241, 1182, 477], \"page_id\": 147}], \"content\": \"<table><tr><td>When this digit is 0, a renewal notice will be sent.</td></tr><tr><td>TRBU SMITH212J ISSDUE000 R 1</td></tr><tr><td>JOHN SMITH</td></tr><tr><td>212 MAIN ST</td></tr><tr><td>FORESTVILLE MD 20747</td></tr></table>\", \"description\": null, \"id\": 3, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [38, 490, 1403, 572], \"page_id\": 147}], \"content\": \"When that number reads ISSDUE000, you have received your last issue unless you renew. You should receive your renewal notice around the same time that you receive the issue with ISSDUE000 on the top line.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [38, 588, 1401, 700], \"page_id\": 147}], \"content\": \"To be sure that your service continues without interruption, please return your renewal notice promptly. If your subscription service is discontinued, simply send your mailing label from any issue to the Superintendent of Documents, Washington, DC 20402-9372 with the proper remittance, and your service will be reinstated.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [38, 713, 1403, 797], \"page_id\": 147}], \"content\": \"To change your address ... please SEND YOUR MAILING LABEL, along with your new address, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9373.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 817, 1400, 892], \"page_id\": 147}], \"content\": \"To inquire about your subscription service ... please SEND YOUR MAILING LABEL, along with your correspondence, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9375.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [40, 950, 234, 987], \"page_id\": 147}], \"content\": \"New Subscribers\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [46, 983, 846, 1018], \"page_id\": 147}], \"content\": \"To order a new subscription please use the 