ll, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [87, 585, 1368, 702], \"page_id\": 6}], \"content\": \"Sold on a subscription basis only (exceptions noted) by the Superintendent of Documents, U.S. Government Printing Office, Washington, D.C. 20402:\\u2020\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [190, 751, 1336, 895], \"page_id\": 6}], \"content\": \"Daily Treasury Statement. Provides summary data on the Treasury's cash and debt operations for the Federal Government. Published each Federal working day. Subscription price: $204 per year (domestic), $255 per year (foreign).\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [183, 917, 1352, 1122], \"page_id\": 6}], \"content\": \"Monthly Treasury Statement of Receipts and Outlays of the United States Government. Provides Federal budget results, including receipts and outlays of funds, the surplus or deficit, and the means of financing the deficit or disposing of the surplus. Preparation based on agency reporting. Subscription price: $27 per year (domestic), $33.75 per year (foreign).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [185, 1135, 1342, 1272], \"page_id\": 6}], \"content\": \"Consolidated Financial Statements of the United States Government (annual). Provides information about Government financial operations on the accrual basis. Single copy price: $2.25.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [183, 1292, 1382, 1464], \"page_id\": 6}], \"content\": \"United States Government Annual Report and Appendix. Annual Report presents budgetary results at the summary level. Appendix presents the individual receipt and appropriation accounts at the detail level. Annual Report single copy price: $2; Appendix free from Financial Management Service.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [88, 1573, 834, 1630], \"page_i