ription\": null, \"id\": 3, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [0, 1124, 82, 1153], \"page_id\": 12}], \"content\": \"Notes\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [0, 1193, 664, 1257], \"page_id\": 12}], \"content\": \"Details of figures may not add to totals because of rounding. r represents Revised, p Preliminary, n.a. Not available.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1376, 46, 1413, 75], \"page_id\": 13}], \"content\": \"VII\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [273, 205, 1199, 276], \"page_id\": 13}], \"content\": \"Nonquarterly Tables and Reports\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [52, 336, 1413, 406], \"page_id\": 13}], \"content\": \"For the convenience of the Treasury Bulletin user, nonquarterly tables and reports are listed below along with the issues in which they appear.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [56, 437, 1381, 1592], \"page_id\": 13}], \"content\": \"<table><tr><th></th><th colspan=\\\"4\\\">Issues</th></tr><tr><th></th><th>Winter</th><th>Spring</th><th>Summer</th><th>Fall</th></tr><tr><td><b>Federal Fiscal Operations</b></td><td></td><td></td><td></td><td></td></tr><tr><td>FFO-4--Summary of internal revenue collections by States and other areas</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td><b>Capital Movements</b></td><td></td><td></td><td></td><td></td></tr><tr><td>CM-III-2--Dollar liabilities to, and dollar claims on, foreigners in countries and areas not regularly reported separately</td><td></td><td>&#10004;</td><td></td><td>&#10004;</td></tr><tr><td><b>Special Reports</b></td><td></td><td></td><td></td><td></td></tr><tr><td>Consolidated Financial Statements of the United States Government</td><td></td><td></td><td>&#10004;</td><td></td></tr><tr><td>Statement of